-- DUMP SQL COMPATIBLE CON SUPABASE POSTGRESQL
-- Tablas: market_snapshot y alert_logs

CREATE TABLE IF NOT EXISTS market_snapshot (
    id SERIAL PRIMARY KEY,
    timestamp TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    fiat VARCHAR(10) NOT NULL,
    asset VARCHAR(10) DEFAULT 'USDT',
    trade_type VARCHAR(10) NOT NULL,
    best_price DOUBLE PRECISION NOT NULL,
    avg_top5_price DOUBLE PRECISION NOT NULL,
    min_limit DOUBLE PRECISION NOT NULL,
    max_limit DOUBLE PRECISION NOT NULL,
    available_asset DOUBLE PRECISION NOT NULL,
    payment_methods TEXT,
    merchant_name VARCHAR(120),
    merchant_finish_rate DOUBLE PRECISION,
    adv_no VARCHAR(64)
);

CREATE TABLE IF NOT EXISTS alert_logs (
    id SERIAL PRIMARY KEY,
    timestamp TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    fiat VARCHAR(10) NOT NULL,
    signal_type VARCHAR(20) NOT NULL,
    price DOUBLE PRECISION NOT NULL,
    channels_sent VARCHAR(100) NOT NULL,
    message TEXT NOT NULL
);

